{"code":"import pandas as pd, numpy as np, statsmodels.api as sm
x=pd.read_csv('data/explore.csv'); cols=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for c in cols:
 d=x[['yield_kg',c,'farm']].dropna(); m=sm.OLS(d.yield_kg,sm.add_constant(pd.concat([d[[c]],pd.get_dummies(d.farm,drop_first=True,dtype=float)],axis=1))).fit()
 print(c,round(m.params[c],3),round(m.pvalues[c],5),round(m.rsquared,4),len(d))
"}
